      Seq_1 := Seq_1 + [Seq[i]];
    } else {
      Seq_2 := Seq_2 + [Seq[i]];
    }
    assert (Seq[..i] + [Seq[i]]) == Seq[..i+1];  
    i := i + 1;
  }
  assert (Seq[..|Seq|] == Seq);  
}


